/**
 * The site's languages, found from the files in src/content/i18n: one `<lang>.json` each. English
 * is the root locale (no prefix in the URL); every other file is served under `/<lang>/`. The
 * pseudo locale `en-XA` is generated by scripts/pseudo.ts and only counts when SITE_PSEUDO is
 * set, so it never reaches a deployed build.
 *
 * Plain JavaScript because astro.config.mjs reads it.
 */
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const I18N_DIR = fileURLToPath(new URL('../content/i18n/', import.meta.url));
export const SOURCE_LANG = 'en';
export const PSEUDO_LANG = 'en-XA';

/** The language codes that have a file, English first and the others in name order. */
export function languageCodes(dir = I18N_DIR) {
	if (!existsSync(dir)) return [SOURCE_LANG];
	const pseudo = Boolean(process.env.SITE_PSEUDO);
	const found = readdirSync(dir)
		.filter((f) => f.endsWith('.json'))
		.map((f) => f.slice(0, -'.json'.length))
		.filter((code) => code !== SOURCE_LANG && (code !== PSEUDO_LANG || pseudo))
		.sort();
	return [SOURCE_LANG, ...found];
}

/** One language file's strings, or an empty object for a language that has none yet. */
export function readStrings(code, dir = I18N_DIR) {
	try {
		return JSON.parse(readFileSync(`${dir}${code}.json`, 'utf8'));
	} catch {
		return {};
	}
}

/**
 * Starlight's `locales` option: English at the root, the rest under their code in lower case
 * (`pt-BR` is served at `/pt-br/`). The file is named by the BCP-47 tag as i18next spells it, which
 * is what it looks the language up by: `sv`, `pt-BR`, `zh-CN`. A four-letter subtag would be
 * respelled (`qps-ploc` becomes `qps-Ploc`), so such a tag finds nothing.
 */
export function starlightLocales() {
	const locales = {};
	for (const code of languageCodes()) {
		const label = readStrings(code)['site.language.name'] ?? code;
		locales[code === SOURCE_LANG ? 'root' : code.toLowerCase()] = { label, lang: code };
	}
	return locales;
}

/** `translations` for a sidebar entry, from the `sidebar.<id>` key of each language that has one. */
export function sidebarTranslations(id) {
	const out = {};
	for (const code of languageCodes()) {
		if (code === SOURCE_LANG) continue;
		const text = readStrings(code)[`sidebar.${id}`];
		if (text) out[code] = text;
	}
	return out;
}
